type Exp = u128;
struct BlockSimulator {
    pub left_tape: Vec<BlockSymbol>,
    pub right_tape: Vec<BlockSymbol>,
    pub state: HigherState,
    pub base_steps: u128,
    pub self_steps: u64,
}
impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use BlockSymbol::*;
        let s0 = match *self {
            Run(t, _) => &format!("{:?}", t),
            _ => &format!("{:?}", self),
        };
        let s_exp = match *self {
            Run(_, n) => if n == 1 { "" } else { &format!("^{}", n) }
            _ => "",
        };
        write!(f, "{}{}", s0, s_exp)
    }
}

impl BlockSymbol {
    fn to_symbols(&self) -> Vec<u8> {
        use BlockSymbol::*;
        match &self {
            L | R => vec![],
            E => vec![1,1,1,0],
            I => vec![1],
            O => vec![0],
            Run(rt, n) => {
                use RunSymbolType::*;
                let v = match rt {
                    X => vec![1,0],
                    W => vec![1,1],
                    U => vec![0,0],
                };
                v.iter().cloned().cycle().take(v.len() * (*n as usize)).collect()
            }
        }
    }
}
// End of customizable code

fn replace<T>(source: &[T], from: &[T], to: &[T]) -> Vec<T>
where
    T: Clone + PartialEq
{
    let mut result = source.to_vec();
    let from_len = from.len();
    let to_len = to.len();

    let mut i = 0;
    while i + from_len <= result.len() {
        if result[i..].starts_with(from) {
            result.splice(i..i + from_len, to.iter().cloned());
            i += to_len;
        } else {
            i += 1;
        }
    }

    result
}

fn collapse_block_runs(v: &mut Vec<BlockSymbol>, t: RunSymbolType) {
    use BlockSymbol::Run;
    let mut i = 0;
    while i + 1 < v.len() {
        if let Some(Run(t2, _)) = v.get(i) {
            if *t2 == t {
                let mut i2 = i + 1;
                let mut n_next = 0;
                loop {
                    if let Some(Run(t3, n)) = v.get(i2) {
                        if *t3 == t {
                            n_next += n;
                            i2 += 1;
                        } else { break; }
                    } else { break; }
                }

                if i2 > i + 1 {
                    v.drain(i+1..i2);
                    let Some(Run(_, n0)) = v.get_mut(i) else { unreachable!() };
                    *n0 += n_next;
                }
            }       
        }

        i += 1;
    }
}

impl BlockSimulator {
    pub fn new() -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L, Run(X, 2), E, Run(U, 1)],
            right_tape: vec![R],
            state: HigherState::RightC,
            base_steps: 37,
            self_steps: 0
        }
    }

    pub fn new_f_config(s: &str, n: Exp) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        let mut left_tape = vec![L];
        for c in s.chars() {
            match c {
                '1' => left_tape.push(I),
                '0' => left_tape.push(O),
                _ => panic!("invalid character"),
            }
        }
        if n > 0 {
            left_tape.push(Run(X, n));
        }
        left_tape = replace(&left_tape, &[I, O], &[Run(X, 1)]);
        collapse_block_runs(&mut left_tape, X);
        left_tape.extend_from_slice(&[E, Run(U, 1)]);

        Self {
            left_tape,
            right_tape: vec![R],
            state: HigherState::RightC,
            base_steps: 0,
            self_steps: 0
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        // D> X I -> W F> ***HALT***
        //
        // 0: * D> 101* 
        // 1: *1 E> 01* 
        // 2: *11 F> 1* 
        // 3: *11 F> * 
        // 3: *11 F> * 
        // Undefined
        if self.state == HigherState::RightD {
            if matches!(self.right_tape[..], [.., BlockSymbol::I, BlockSymbol::Run(RunSymbolType::X, 1)]) {
                self.right_tape.pop();
                self.right_tape.pop();
                add_or_merge_run(&mut self.left_tape, RunSymbolType::W, 1);
                self.base_steps += 3;
                self.self_steps += 1;
                return Err(SimError::Halted);
            }
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }

    pub fn is_f_config(&self) -> bool {
        self.state == HigherState::RightC && self.right_tape == vec![BlockSymbol::R] 
            && matches!(self.left_tape[..], [.., BlockSymbol::E, BlockSymbol::Run(RunSymbolType::U, 1)])
    }

    pub fn try_parse_f_config(mut self) -> Option<(String, usize)> {
        if self.state != HigherState::RightC || self.right_tape != vec![S::R] {
            return None;
        }
        {
            use BlockSymbol::*;
            use RunSymbolType::*;
            self.left_tape = replace(&self.left_tape, &[I, O], &[Run(X, 1)]);
            self.left_tape = replace(&self.left_tape, &[Run(W, 1), O], &[I, Run(X, 1)]);
            collapse_block_runs(&mut self.left_tape, X);
        }

        use BlockSymbol as S;
        use RunSymbolType as RT;
        if let [S::L, middle @ .., S::Run(RT::X, n), S::E, S::Run(RT::U, 1)] = &self.left_tape[..] {
            let left_s_u8: Vec<u8> = middle.iter().flat_map(BlockSymbol::to_symbols).collect();
            let left_str: String = left_s_u8.iter().map(|x| match x {
                0 => '0',
                1 => '1',
                _ => unreachable!()
            }).collect();
            if left_str.ends_with("10") {
                eprintln!("failed to parse, left string ends with X");
                return None;
            }
            let n = *n as usize;
            Some((left_str, n))
        } else {
            None
        }
    }
}

#[derive(Debug, PartialEq)]
enum VampireConfig {
    F(String, usize),
    Halt
}

fn run_to_next_config(s: &str, n: Exp, verbose: bool) -> VampireConfig {
    let mut sim = BlockSimulator::new_f_config(s, n);
    if verbose {
        println!("{sim}");
    }
    loop {
        let res = sim.step();
        if res.is_err() {
            // println!("{}, {:?}", sim, res);
            if res == Err(SimError::Halted) {
                return VampireConfig::Halt;
            } else {
                panic!();
            }
        }
        if verbose {
            println!("{}", sim);
        }
        if sim.is_f_config() {
            if let Some((left_str, n_new)) = sim.try_parse_f_config() {
                return VampireConfig::F(left_str, n_new);
                // println!("\"{left_str}\" {n}");
            } else {
                panic!("failed to parse");
            }
        }
    }
}

/// F { s, n_const } means F(s, 3n + n_const)
#[derive(Debug, PartialEq)]
enum RuleResult {
    F { s: String, n_const: usize },
    Halt
}

/// F { s, n_const } means F(s, 3n + n_const)
#[derive(Debug, PartialEq, Clone)]
enum IndexedRuleResult {
    F { s_i: usize, n_const: usize },
    Halt
}

impl fmt::Display for RuleResult {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::F { s, n_const} => write!(f, "(\"{}\", 3n+{})", s, n_const),
            Self::Halt => write!(f, "Halt"),
        }
    }
}

impl fmt::Display for IndexedRuleResult {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::F { s_i, n_const} => write!(f, "([{}], 3n+{})", s_i, n_const),
            Self::Halt => write!(f, "Halt"),
        }
    }
}

/// parity: false = even n, true = odd n
/// not rigorous
fn infer_rule_with_parity(s: String, parity: bool) -> RuleResult {
    let n0 = if parity { 1 } else { 0 };
    const N_TEST: u32 = 10;

    let config0 = run_to_next_config(&s, n0, false);
    match config0 {
        VampireConfig::F(s_new, n_new) => {
            let mut n_out = n_new;
            let mut n_in = n0;
            for _ in 0..N_TEST {
                n_in += 2;
                if let VampireConfig::F(s_out, n1) = run_to_next_config(&s, n_in, false) {
                    assert_eq!(s_new, s_out);
                    assert_eq!(n_out + 3, n1);
                    n_out = n1;
                } else {
                    panic!();
                }
            }
            RuleResult::F { s: s_new, n_const: n_new }
        }
        VampireConfig::Halt => {
            let mut n = n0;
            for _ in 0..N_TEST {
                n += 2;
                assert!(run_to_next_config(&s, n, false) == VampireConfig::Halt);
            }
            RuleResult::Halt
        }
    }
}

#[derive(Debug)]
struct Rule {
    s_in: String,
    even: RuleResult,
    odd: RuleResult
}

impl Rule {
    fn to_graphviz_str(&self) -> String {
        let s_in_g = if self.s_in == "" {
            "empty"
        } else {
            &self.s_in
        };

        let near_halt = if self.even == RuleResult::Halt || self.odd == RuleResult::Halt {
            &format!("{} [style=filled, fillcolor=\"yellow\"];\n", s_in_g)
        } else {
            ""
        };

        let s_even_g = if let RuleResult::F { s, n_const: _ } = &self.even {
            if s == "" { "empty" } else { &s }
        } else {
            "halt"
        };

        let s_odd_g = if let RuleResult::F { s, n_const: _ } = &self.odd {
            if s == "" { "empty" } else { &s }
        } else {
            "halt"
        };
        format!("{near_halt}{s_in_g} -> {s_even_g} [taillabel=\"0\"]\n{s_in_g} -> {s_odd_g} [taillabel=\"1\"]")
    }
}

fn infer_rule(s: String) -> Rule {
    Rule {
        s_in: s.clone(),
        even: infer_rule_with_parity(s.clone(), false),
        odd: infer_rule_with_parity(s, true)
    }
}

fn search_rules(max_rule_count: usize) -> Vec<Rule> {
    use std::collections::{BTreeSet, HashSet};

    let mut visited: HashSet<String> = HashSet::new();
    let mut frontier: BTreeSet<(usize, String)> = BTreeSet::new();
    let mut rules = Vec::new();
    frontier.insert((0, "".to_owned()));

    while rules.len() < max_rule_count && let Some((_, s)) = frontier.pop_first() {
        // println!("{s}");
        visited.insert(s.clone());
        let rule = infer_rule(s);

        if let RuleResult::F { s: s_odd, n_const: _ } = &rule.odd {
            if !visited.contains(s_odd) {
                frontier.insert((s_odd.len(), s_odd.clone()));
            }
        }
        if let RuleResult::F { s: s_even, n_const: _ } = &rule.even {
            if !visited.contains(s_even) {
                frontier.insert((s_even.len(), s_even.clone()));
            }
        }
        // println!("{:?}", &rule);
        rules.push(rule);
    }

    rules
}

#[derive(Debug, Clone)]
struct SimRuleCache {
    S_list: Vec<String>,
    index_lookup: HashMap<String, usize>,
    even_results: Vec<Option<IndexedRuleResult>>,
    odd_results: Vec<Option<IndexedRuleResult>>,
}

impl SimRuleCache {
    fn new() -> Self {
        Self {
            S_list: vec!["".to_owned()],
            index_lookup: HashMap::from([("".to_owned(), 0)]),
            even_results: vec![None],
            odd_results: vec![None],
        }
    }

    fn get_or_insert_index(&mut self, s: String) -> usize {
        if let Some(i) = self.index_lookup.get(&s) {
            *i
        } else {
            let idx = self.S_list.len();
            self.S_list.push(s.clone());
            self.index_lookup.insert(s, idx);
            self.even_results.push(None);
            self.odd_results.push(None);
            idx
        }
    }

    fn fill_rule(&mut self, i: usize, parity: bool) {
        let r_new = match infer_rule_with_parity(self.S_list[i].clone(), parity) {
            RuleResult::F { s, n_const } => {
                let i_new = self.get_or_insert_index(s);
                IndexedRuleResult::F { s_i: i_new, n_const }
            },
            RuleResult::Halt => IndexedRuleResult::Halt,
        };

        if parity {
            self.odd_results[i] = Some(r_new);
        } else {
            self.even_results[i] = Some(r_new);
        }
    }

    /// parity: false = even n, true = odd n
    fn get_result_by_index(&mut self, i: usize, parity: bool) -> &IndexedRuleResult {
        if parity && self.odd_results[i].is_none() || (!parity && self.even_results[i].is_none()) {
            self.fill_rule(i, parity);
        }

        if parity {
            self.odd_results[i].as_ref().unwrap()
        } else {
            self.even_results[i].as_ref().unwrap()
        }
    }
}

impl fmt::Display for SimRuleCache {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        for (i, S) in self.S_list.iter().enumerate() {
            write!(f, "[{i}] {S} => (even) ")?;
            match &self.even_results[i] {
                Some(r) => write!(f, "{}", r)?,
                None => write!(f, "??")?,
            }
            write!(f, ", (odd) ")?;
            match &self.odd_results[i] {
                Some(r) => write!(f, "{}", r)?,
                None => write!(f, "??")?,
            }
            writeln!(f)?;
        }
        Ok(())
    }
}

fn n_next(n_curr: &u128, n_const: &usize) -> Option<u128> {
    let n_red = n_curr / 2;
    match n_red.checked_mul(3) {
        Some(n2) => n2.checked_add(*n_const as u128),
        None => None,
    }
}

fn sim_to_overflow(verbose: bool) -> (u64, usize, u128, SimRuleCache) {
    let mut n: u128 = 2;
    let mut s_i: usize = 0;
    let mut cache = SimRuleCache::new();

    let mut iter = 0;

    loop {
        let parity = n % 2 == 1;
        match cache.get_result_by_index(s_i, parity) {
            IndexedRuleResult::F { s_i: s_i_new, n_const } => {
                match n_next(&n, n_const) {
                    Some(n_next) => { 
                        s_i = *s_i_new;
                        n = n_next;
                    }
                    None => {
                        if verbose {
                            println!("Overflow");
                        }
                        break;
                    }
                }
            }
            IndexedRuleResult::Halt => {
                if verbose {
                    println!("halt");
                }
                break;
            }
        }
        iter += 1;
        if verbose {
            println!("{iter}: \"{}\", {}", cache.S_list[s_i], n);
        }
    }

    if verbose {
        println!("{iter}: \"{}\", {}; {:?}", cache.S_list[s_i], n, cache);
    }
    
    (iter, s_i, n, cache)
}

use rand::Rng;
use rand_pcg::rand_core::SeedableRng;
use rand_pcg::Pcg64;
use std::time::Instant;
fn monte_carlo_sim(iter: u64, s_i: usize, n0: u128, mut cache: SimRuleCache) {
    use pretty_duration::{pretty_duration, PrettyDurationOptions, PrettyDurationOutputFormat};

    let mut rng = Pcg64::from_rng(&mut rand::rng());

    let mut iter = iter;
    let mut s_i = s_i;

    let max_mod: u64 = 1 << 62;
    let mut n = (n0 % max_mod as u128) as u64;
    let mut modulus = max_mod;

    let mut time = Instant::now();

    const COMPACT_OPTIONS: PrettyDurationOptions = PrettyDurationOptions {
        output_format: Some(PrettyDurationOutputFormat::Compact),
        singular_labels: None,
        plural_labels: None,
    };

    loop {
        let parity = n % 2 == 1;
        match cache.get_result_by_index(s_i, parity) {
            IndexedRuleResult::F { s_i: s_i_new, n_const } => {
                // divide (n, modulus) by 2
                if modulus > 2 {
                    n /= 2;
                    modulus /= 2;
                } else {
                    // out of bits; now randomize
                    modulus = max_mod;
                    n = rng.random_range(0..max_mod);
                }
                n = (3*n) % modulus;
                n = (n + *n_const as u64) % modulus;

                s_i = *s_i_new;

                iter += 1;
            }
            IndexedRuleResult::Halt => {
                iter += 1;
                break;
            }
        }
        if iter % 1000000000 == 0 {
            let duration_s = pretty_duration(&time.elapsed(), Some(COMPACT_OPTIONS));
            println!("{iter}, cache size {}, {duration_s}", cache.S_list.len());

            time = Instant::now();
            // if iter > 4000000000 {
            //     break;
            // }
        }
    }

    println!("halted after {iter} steps on {}", cache.S_list[s_i]);
    println!("cache:\n{cache}");
}

